.sl-feature-dashboard {
    background-color: var(--smartlearn-bg);
    color: var(--smartlearn-text);
    font-family: var(--smartlearn-body-font, inherit);
    padding-block: clamp(3rem, 6vw, 5.5rem);
}
.sl-feature-dashboard h2,
.sl-feature-dashboard h3 {
    font-family: var(--smartlearn-heading-font, inherit);
}
.sl-feature-dashboard .sl-text-primary { color: var(--smartlearn-primary); }
.sl-feature-dashboard .sl-text-emphasis { color: var(--smartlearn-text); }
.sl-feature-dashboard .sl-text-muted { color: var(--smartlearn-text-muted); }
.sl-feature-dashboard .sl-bg-card {
    background-color: var(--smartlearn-card-bg);
    border: 1px solid var(--smartlearn-card-border);
}
.sl-feature-dashboard .sl-accent-soft {
    background-color: var(--smartlearn-card-bg);
    background-color: color-mix(in srgb, var(--smartlearn-primary) 12%, transparent);
}
.sl-feature-dashboard .sl-border { border-color: var(--smartlearn-card-border); }
.sl-feature-dashboard .sl-media-fallback {
    background-color: var(--smartlearn-card-bg);
    color: var(--smartlearn-text-muted);
}
.sl-feature-dashboard .sl-dashboard-mockup {
    aspect-ratio: 16 / 9;
    max-width: 1000px;
    transform: perspective(1000px) rotateX(5deg) scale(0.95);
    transition: transform 0.6s cubic-bezier(0.165, 0.84, 0.44, 1), box-shadow 0.6s ease;
}
@media (hover: hover) and (prefers-reduced-motion: no-preference) {
    .sl-feature-dashboard .sl-dashboard-mockup:hover {
        transform: perspective(1000px) rotateX(0deg) scale(1);
    }
    .sl-feature-dashboard .sl-dashboard-mockup:hover .sl-dashboard-frame {
        box-shadow: 0 2rem 4rem color-mix(in srgb, var(--smartlearn-text) 16%, transparent);
    }
}
.sl-feature-dashboard .sl-widget-start {
    bottom: -20px;
    inset-inline-start: -20px;
}
.sl-feature-dashboard .sl-widget-end {
    top: 40px;
    inset-inline-end: -30px;
}
.sl-feature-dashboard .sl-widget-primary {
    background-color: var(--smartlearn-primary);
    color: var(--smartlearn-btn-text);
}
.sl-feature-dashboard .sl-widget-sub {
    opacity: 0.9;
}
.sl-feature-dashboard .sl-floating-widget {
    animation: sl-dashboard-float 6s ease-in-out infinite;
}
.sl-feature-dashboard .sl-dashboard-mockup:hover .sl-floating-widget {
    animation-play-state: paused;
}
@keyframes sl-dashboard-float {
    0% { transform: translateY(0); }
    50% { transform: translateY(-10px); }
    100% { transform: translateY(0); }
}
@media (prefers-reduced-motion: reduce) {
    .sl-feature-dashboard .sl-floating-widget { animation: none; }
    .sl-feature-dashboard .sl-dashboard-mockup {
        transform: none;
        transition: none;
    }
}
